(()=>{
const scriptRoot=new URL('.',document.currentScript.src),q=s=>document.querySelector(s),api=path=>new URL(`api/${path}`,scriptRoot).href;
let view=null,selectedId=null,proposal=null,busy=false;
const polityClass=id=>`polity-${Math.max(0,view.polities.findIndex(item=>item.polityId===id))}`;
const fmt=value=>new Intl.NumberFormat('zh-CN').format(value);
function setBusy(value,message){busy=value;['#macroStep','#macroRun','#macroReset','#macroAskLlm','#macroApplyProposal'].forEach(id=>{const el=q(id);if(el)el.disabled=value||(id==='#macroAskLlm'&&!selectedId)});if(message)q('#macroStatus').textContent=message}
async function post(path,body){const response=await fetch(api(path),{method:'POST',headers:{'Content-Type':'application/json','X-Worldforge-Simulation':'1'},body:JSON.stringify(body)}),data=await response.json();if(!response.ok)throw Error(data.error||'请求失败');return data}
function riskClass(value,high=65,medium=50){return value>=high?'good':value>=medium?'medium':'bad'}
function mapMetric(region){const layer=q('#macroLayer').value;if(layer==='stability')return `稳定 ${region.stability}`;if(layer==='food')return `粮食 ${region.food}`;if(layer==='population')return `人口 ${region.population}`;return view.polities.find(item=>item.polityId===region.ownerId)?.title||region.ownerId}
function layerColor(region,layer){if(layer==='stability'){const hue=Math.round(Math.max(0,Math.min(100,region.stability))*1.15);return `hsl(${hue} 38% 43%)`}if(layer==='food'){const light=32+Math.round(Math.min(70,region.food)/70*25);return `hsl(42 58% ${light}%)`}if(layer==='population'){const light=34+Math.round(Math.min(160,region.population)/160*22);return `hsl(208 42% ${light}%)`}return''}
function renderMap(){const map=q('#macroMap'),layer=q('#macroLayer').value;map.replaceChildren(...view.regions.map(region=>{const button=document.createElement('button');button.type='button';button.className=`macro-region ${polityClass(region.ownerId)} ${selectedId===region.regionId?'selected':''}`;button.style.setProperty('--q',region.map.q);button.style.setProperty('--r',region.map.r);button.style.setProperty('--offset',region.map.r%2?11.5:0);if(layer!=='owner')button.style.background=layerColor(region,layer);button.dataset.regionId=region.regionId;button.title=`${region.title} · ${mapMetric(region)}`;button.setAttribute('aria-label',button.title);const name=document.createElement('strong'),metric=document.createElement('span');name.textContent=region.title;metric.textContent=mapMetric(region);button.append(name,metric);button.onclick=()=>{selectedId=region.regionId;proposal=null;render()};return button}));const labels={owner:'按政体着色',stability:'稳定：红低绿高',food:'粮食：深色低浅色高',population:'人口：深色低浅色高'};q('#macroMapLegend').textContent=labels[layer]}
function renderPolities(){q('#macroPolities').replaceChildren(...view.polities.map((polity,index)=>{const card=document.createElement('article');card.className=`macro-polity polity-${index}`;card.innerHTML=`<i></i><div><strong>${polity.title}</strong><span>${polity.regionCount} 地区 · 人口 ${fmt(polity.population)}</span></div><em>财政 ${polity.treasury}</em>`;return card}))}
function renderLocal(){const region=view.regions.find(item=>item.regionId===selectedId),box=q('#macroLocal');q('#macroAskLlm').disabled=busy||!region;q('#macroSelectedId').textContent=region?.regionId||'未选择';if(!region){box.innerHTML='<p class="simulation-empty">从左侧地图选择一个地区。</p>';q('#macroProposal').hidden=true;q('#macroApplyProposal').hidden=true;return}const owner=view.polities.find(item=>item.polityId===region.ownerId),neighbors=region.neighbors.map(id=>view.regions.find(item=>item.regionId===id)).filter(Boolean);box.innerHTML=`<div class="macro-local-title"><div><h3>${region.title}</h3><span>${owner.title} · ${region.terrain}</span></div><b class="${riskClass(region.stability)}">稳定 ${region.stability}</b></div><div class="macro-local-stats"><span>人口<strong>${fmt(region.population)}</strong></span><span>粮食<strong>${region.food}</strong></span><span>产粮<strong>${region.foodOutput}</strong></span><span>工业<strong>${region.industry}</strong></span><span>基建<strong>${region.infrastructure}</strong></span><span>驻军<strong>${region.garrison}</strong></span></div><div class="macro-neighbors"><small>相邻地区</small>${neighbors.map(item=>`<button type="button" data-neighbor="${item.regionId}">${item.title}<span>${item.ownerId===region.ownerId?'本国':'邻国'} · 稳定 ${item.stability}</span></button>`).join('')}</div>`;box.querySelectorAll('[data-neighbor]').forEach(button=>button.onclick=()=>{selectedId=button.dataset.neighbor;proposal=null;render()});renderProposal()}
function renderProposal(){const box=q('#macroProposal'),apply=q('#macroApplyProposal');if(!proposal){box.hidden=true;apply.hidden=true;return}box.hidden=false;apply.hidden=false;const head=document.createElement('div'),source=document.createElement('span'),title=document.createElement('strong'),reason=document.createElement('p'),outcome=document.createElement('small'),type=document.createElement('code');source.textContent=proposal.source==='llm'?`LLM · ${proposal.model||'model'}`:'规则回退';title.textContent=proposal.title;reason.textContent=proposal.rationale;outcome.textContent=proposal.expectedOutcome;type.textContent=proposal.action.type;head.append(source,title);box.replaceChildren(head,reason,outcome,type);if(proposal.fallbackReason){const fallback=document.createElement('em');fallback.textContent=`回退原因：${proposal.fallbackReason}`;box.append(fallback)}}
function renderEvents(){const labels={'macro.quarter_summary':'季度结算','macro.trade':'粮食流动','macro.shortage':'粮食短缺','macro.migration':'人口迁移','macro.border_change':'边界变化','macro.local_action':'局部干预'};q('#macroEvents').replaceChildren(...(view.recentEvents.length?view.recentEvents.map(event=>{const row=document.createElement('div');row.className='simulation-log-row';row.innerHTML=`<strong>Q${event.tick}</strong><span>${event.payload.summary||labels[event.type]||event.type}</span><em>${labels[event.type]||'事件'}</em>`;return row}):[Object.assign(document.createElement('p'),{className:'simulation-empty',textContent:'尚无事件。'})]))}
function renderChart(){const history=view.history.slice(-12),box=q('#macroChart');if(!history.length){box.innerHTML='<p class="simulation-empty">推进季度后显示趋势。</p>';return}const keys=[['population','人口'],['food','粮食'],['averageStability','稳定']],width=560,height=190,pad=24;const paths=keys.map(([key,label],index)=>{const values=history.map(item=>item[key]),min=Math.min(...values),max=Math.max(...values),range=max-min||1,points=values.map((value,i)=>`${pad+i*(width-pad*2)/Math.max(1,values.length-1)},${height-pad-(value-min)*(height-pad*2)/range}`).join(' ');return `<polyline class="line-${index}" points="${points}"/><text x="${pad+index*90}" y="14" class="label-${index}">${label} ${values.at(-1)}</text>`}).join('');box.innerHTML=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="最近季度人口、粮食与稳定度趋势">${paths}</svg>`}
function render(){q('#macroClock').textContent=`第 ${view.clock.year} 年 · Q${view.clock.quarter}`;q('#macroTick').textContent=`已结算 ${view.clock.elapsedQuarters} 季度`;q('#macroPopulation').textContent=fmt(view.totals.population);q('#macroFood').textContent=fmt(view.totals.food);q('#macroStability').textContent=view.totals.averageStability;q('#macroReplay').textContent=view.verification.replayVerified?'历史重放一致':'重放校验失败';q('#macroConnection').textContent='宏观实例已连接';renderMap();renderPolities();renderLocal();renderEvents();renderChart()}
async function refresh(){if(busy)return;setBusy(true,'正在读取宏观世界状态…');try{const response=await fetch(api('macro')),data=await response.json();if(!response.ok)throw Error(data.error||'读取失败');view=data;if(selectedId&&!view.regions.some(item=>item.regionId===selectedId))selectedId=null;render();q('#macroStatus').textContent='宏观状态已同步。选择地区可请求局部提案。'}catch(error){q('#macroConnection').textContent='连接失败';q('#macroStatus').textContent=`无法读取：${error.message}`}finally{setBusy(false)}}
async function advance(quarters=1,actions=[]){if(!view||busy)return;setBusy(true,quarters>1?`正在连续结算 ${quarters} 个季度…`:'正在结算下一季度…');try{view=quarters===1?await post('macro/step',{expectedStateVersion:view.instance.stateVersion,actions}):await post('macro/run',{expectedStateVersion:view.instance.stateVersion,quarters});proposal=null;render();q('#macroStatus').textContent=`已推进 ${quarters} 季度；规则状态与历史重放一致。`}catch(error){q('#macroStatus').textContent=`推进失败：${error.message}`}finally{setBusy(false)}}
async function ask(){if(!selectedId||busy)return;setBusy(true,'正在向 LLM 提供选中地区的有限上下文…');try{proposal=await post('macro/local-proposal',{regionId:selectedId});renderProposal();q('#macroStatus').textContent=proposal.source==='llm'?'LLM 提案已通过规则预校验，等待你采纳。':'模型不可用，已给出规则回退提案。'}catch(error){q('#macroStatus').textContent=`提案失败：${error.message}`}finally{setBusy(false)}}
q('#refreshMacro').onclick=refresh;q('#macroStep').onclick=()=>advance();q('#macroRun').onclick=()=>advance(4);q('#macroAskLlm').onclick=ask;q('#macroApplyProposal').onclick=()=>proposal&&advance(1,[proposal.action]);q('#macroLayer').onchange=()=>view&&renderMap();q('#macroReset').onclick=async()=>{if(!view||busy||!confirm('重置会清空 W98 的季度、行动和事件记录。继续吗？'))return;setBusy(true,'正在重置 W98…');try{view=await post('macro/reset',{expectedStateVersion:view.instance.stateVersion});proposal=null;render();q('#macroStatus').textContent='W98 已回到第 1 年 Q1。'}catch(error){q('#macroStatus').textContent=`重置失败：${error.message}`}finally{setBusy(false)}};
window.WorldforgeMacro={refresh};
})();
